import{_ as e,a0 as p,w as r,s as a,ao as i,I as o,x as u,a1 as s,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在雙啓動或單啓動模式下重新安裝 Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"如何在雙啓動或單啓動模式下重新安裝 Ubuntu | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在雙啓動或單啓動模式下重新安裝 Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在雙啓動或單啓動模式下重新安裝 Ubuntu | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190814 How to Reinstall Ubuntu in Dual Boot or Single Boot Mode","title":"如何在雙啓動或單啓動模式下重新安裝 Ubuntu","tag":"201908","desc":""},"relativePath":"201908/20190814 How to Reinstall Ubuntu in Dual Boot or Single Boot Mode.md","filePath":"[post].md"}'),b={name:"201908/20190814 How to Reinstall Ubuntu in Dual Boot or Single Boot Mode.md"};function d(U,t,m,f,T,g){const n=p("Link");return r(),a("div",null,[t[25]||(t[25]=i('<h1 id="如何在雙啓動或單啓動模式下重新安裝-ubuntu" tabindex="-1">如何在雙啓動或單啓動模式下重新安裝 Ubuntu <a class="header-anchor" href="#如何在雙啓動或單啓動模式下重新安裝-ubuntu" aria-label="Permalink to “如何在雙啓動或單啓動模式下重新安裝 Ubuntu”">​</a></h1><p>如果你弄壞了你的 Ubuntu 系統，並嘗試了很多方法來修復，你最終放棄並採取簡單的方法：重新安裝 Ubuntu。</p><p>我們一直遇到這樣一種情況，重新安裝 Linux 似乎比找出問題並解決來得更好。排查 Linux 故障能教你很多，但你不會總是花費更多時間來修復損壞的系統。</p><p>據我所知，Ubuntu 中沒有像 Windows 那樣的系統恢復分區。那麼，問題出現了：如何重新安裝 Ubuntu？讓我告訴你如何重新安裝 Ubuntu。</p><p><strong>警告！</strong></p><blockquote><p><strong>磁盤分區始終是一項危險的任務。我強烈建議你在外部磁盤上備份數據。</strong></p></blockquote><h3 id="如何重新安裝-ubuntu-linux" tabindex="-1">如何重新安裝 Ubuntu Linux <a class="header-anchor" href="#如何重新安裝-ubuntu-linux" aria-label="Permalink to “如何重新安裝 Ubuntu Linux”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/08/Reinstall-Ubuntu.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>以下是重新安裝 Ubuntu 的步驟。</p><h4 id="步驟-1-創建一個-live-usb" tabindex="-1">步驟 1：創建一個 live USB <a class="header-anchor" href="#步驟-1-創建一個-live-usb" aria-label="Permalink to “步驟 1：創建一個 live USB”">​</a></h4>',10)),o("p",null,[t[1]||(t[1]=u("首先，在網站上下載 Ubuntu。你可以下載",-1)),s(n,{href:"https://itsfoss.com/which-ubuntu-install/"},{default:l(()=>[...t[0]||(t[0]=[u("任何需要的 Ubuntu 版本",-1)])]),_:1}),t[2]||(t[2]=u("。",-1))]),o("ul",null,[o("li",null,[s(n,{href:"https://ubuntu.com/download/desktop"},{default:l(()=>[...t[3]||(t[3]=[u("下載 Ubuntu",-1)])]),_:1})])]),t[26]||(t[26]=o("p",null,"獲得 ISO 鏡像後，就可以創建 live USB 了。如果 Ubuntu 系統仍然可以使用，那麼可以使用 Ubuntu 提供的啓動盤創建工具創建它。",-1)),o("p",null,[t[5]||(t[5]=u("如果無法使用你的 Ubuntu，那麼你可以使用其他系統。你可以參考這篇文章來學習",-1)),s(n,{href:"https://itsfoss.com/create-live-usb-of-ubuntu-in-windows/"},{default:l(()=>[...t[4]||(t[4]=[u("如何在 Windows 中創建 Ubuntu 的 live USB",-1)])]),_:1}),t[6]||(t[6]=u("。",-1))]),t[27]||(t[27]=i('<h4 id="步驟-2-重新安裝-ubuntu" tabindex="-1">步驟 2：重新安裝 Ubuntu <a class="header-anchor" href="#步驟-2-重新安裝-ubuntu" aria-label="Permalink to “步驟 2：重新安裝 Ubuntu”">​</a></h4><p>有了 Ubuntu 的 live USB 之後將其插入 USB 端口。重新啓動系統。在啓動時，按下 <code>F2</code>/<code>F10</code>/<code>F12</code> 之類的鍵進入 BIOS 設置，並確保已設置 “Boot from Removable Devices/USB”。保存並退出 BIOS。這將啓動進入 live USB。</p><p>進入 live USB 後，選擇安裝 Ubuntu。你將看到選擇語言和鍵盤佈局這些常用選項。你還可以選擇下載更新等。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/08/reinstall-ubuntu-1.jpg?resize=800%2C473&amp;ssl=1" alt="Go ahead with regular installation option"></p><p>現在是重要的步驟。你應該看到一個“<ruby>安裝類型<rt>Installation Type</rt></ruby>”頁面。你在屏幕上看到的內容在很大程度上取決於 Ubuntu 如何處理系統上的磁盤分區和安裝的操作系統。</p><p>在此步驟中仔細閲讀選項及它的細節。注意每個選項的説明。屏幕上的選項可能在不同的系統中看上去不同。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/reinstall-ubuntu-dual-boot.jpg?ssl=1" alt="Reinstall Ubuntu option in dual boot mode"></p><p>在這裏，它發現我的系統上安裝了 Ubuntu 18.04.2 和 Windows，它給了我一些選項。</p><p>第一個選項是擦除 Ubuntu 18.04.2 並重新安裝它。它告訴我它將刪除我的個人數據，但它沒有説刪除所有操作系統（即 Windows）。</p><p>如果你非常幸運或處於單一啓動模式，你可能會看到一個“<ruby>重新安裝 Ubuntu<rt>Reinstall Ubuntu</rt></ruby>”的選項。此選項將保留現有數據，甚至嘗試保留已安裝的軟件。如果你看到這個選項，那麼就用它吧。</p><p><strong>雙啓動系統注意</strong></p>',11)),o("blockquote",null,[o("p",null,[o("strong",null,[t[8]||(t[8]=u("如果你是雙啓動 Ubuntu 和 Windows，並且在重新安裝中，你的 Ubuntu 系統看不到 Windows，你必須選擇 “Something else” 選項並從那裏安裝 Ubuntu。我已經在",-1)),s(n,{href:"https://itsfoss.com/replace-linux-from-dual-boot/"},{default:l(()=>[...t[7]||(t[7]=[u("在雙啓動下安裝 Linux 的過程",-1)])]),_:1}),t[9]||(t[9]=u("這篇文章中説明了。",-1))])])]),t[28]||(t[28]=i('<p>對我來説，沒有重新安裝並保留數據的選項，因此我選擇了“<ruby>擦除 Ubuntu 並重新安裝<rt>Erase Ubuntu and reinstall</rt></ruby>”。該選項即使在 Windows 的雙啓動模式下，也將重新安裝 Ubuntu。</p><p>我建議為 <code>/</code> 和 <code>/home</code> 使用單獨分區就是為了重新安裝。這樣，即使重新安裝 Linux，也可以保證 <code>/home</code> 分區中的數據安全。我已在此視頻中演示過：</p><p>選擇重新安裝 Ubuntu 後，剩下就是單擊下一步。選擇你的位置、創建用户賬户。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/reinstall-ubuntu-3.jpg?ssl=1" alt="Just go on with the installation options"></p><p>以上完成後，你就完成重裝 Ubuntu 了。</p><p>在本教程中，我假設你已經知道我説的東西，因為你之前已經安裝過 Ubuntu。如果需要澄清任何一個步驟，請隨時在評論欄詢問。</p><hr>',7)),o("p",null,[t[11]||(t[11]=u("via: ",-1)),s(n,{href:"https://itsfoss.com/reinstall-ubuntu/"},{default:l(()=>[...t[10]||(t[10]=[u("https://itsfoss.com/reinstall-ubuntu/",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=u("作者：",-1)),s(n,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...t[12]||(t[12]=[u("Abhishek Prakash",-1)])]),_:1}),t[17]||(t[17]=u(" 選題：",-1)),s(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[13]||(t[13]=[u("lujun9972",-1)])]),_:1}),t[18]||(t[18]=u(" 譯者：",-1)),s(n,{href:"https://github.com/geekpi"},{default:l(()=>[...t[14]||(t[14]=[u("geekpi",-1)])]),_:1}),t[19]||(t[19]=u(" 校對：",-1)),s(n,{href:"https://github.com/wxy"},{default:l(()=>[...t[15]||(t[15]=[u("wxy",-1)])]),_:1})]),o("p",null,[t[22]||(t[22]=u("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[20]||(t[20]=[u("LCTT",-1)])]),_:1}),t[23]||(t[23]=u(" 原創編譯，",-1)),s(n,{href:"https://linux.cn/"},{default:l(()=>[...t[21]||(t[21]=[u("Linux中國",-1)])]),_:1}),t[24]||(t[24]=u(" 榮譽推出",-1))])])}const B=e(b,[["render",d]]);export{x as __pageData,B as default};
